// Define the DateTime64 enum with two variants: Nat and Valid
#[derive(Debug)]
enum DateTime64 {
    Nat,
    Valid(u64),
}

// Implement the isnat function
fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Map each DateTime64 to a boolean value
    x.iter().map(|date_time| {
        match date_time {
            DateTime64::Nat => true,        // Return true for Nat case
            DateTime64::Valid(_) => false,  // Return false for Valid case
        }
    }).collect() // Collect the results into a Vec<bool>
}

// Example usage
